          <button id="suggest-questions" class="secondary" ${!e.messages.some(u=>u.role==="elderly")||e.suggestionsLoading||e.interviewEnded?"disabled":""}>${e.suggestionsLoading?"準備中…":"生成追問建議"}</button>
